#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdint.h>

/* ARNAUD state struct inferred from scipy's pack_dict_to_state_d */
typedef struct {
    double tol;            /* 0x00 */
    double getv0_rnorm0;   /* 0x08 */
    double aitr_betaj;     /* 0x10 */
    double aitr_rnorm1;    /* 0x18 */
    double aitr_wnorm;     /* 0x20 */
    double aup2_rnorm;     /* 0x28 */
    int which;             /* 0x30 */
    int ido;               /* 0x34 */
    int info;              /* 0x38 */
    int bmat;              /* 0x3c */
    int mode;              /* 0x40 */
    int n;                 /* 0x44 */
    int ncv;               /* 0x48 */
    int nev;               /* 0x4c */
    int shift;             /* 0x50 */
    int maxiter;           /* 0x54 */
    int nconv;             /* 0x58 */
    int iter;              /* 0x5c */
    int np;                /* 0x60 */
    int getv0_first;       /* 0x64 */
    int getv0_iter;        /* 0x68 */
    int getv0_itry;        /* 0x6c */
    int getv0_orth;        /* 0x70 */
    int aitr_iter;         /* 0x74 */
    int aitr_j;            /* 0x78 */
    int aitr_orth1;        /* 0x7c */
    int aitr_orth2;        /* 0x80 */
    int aitr_restart;      /* 0x84 */
    int aitr_step3;        /* 0x88 */
    int aitr_step4;        /* 0x8c */
    int aitr_ierr;         /* 0x90 */
    int aup2_initv;        /* 0x94 */
    int aup2_iter;         /* 0x98 */
    int aup2_getv0;        /* 0x9c */
    int aup2_cnorm;        /* 0xa0 */
    int aup2_kplusp;       /* 0xa4 */
    int aup2_nev;          /* 0xa8 */
    int aup2_nev0;         /* 0xac */
    int aup2_np0;          /* 0xb0 */
    int aup2_numcnv;       /* 0xb4 */
    int aup2_update;       /* 0xb8 */
    int aup2_ushift;       /* 0xbc */
} arnaud_state_d;

/* which codes from scipy WHICH_DICT — we'll print them from python and hardcode after.
   For now accept which as int. */

extern void ARNAUD_dnaupd(arnaud_state_d *state, double *resid, double *v,
                          int *ipntr, double *workd, double *workl);

/* CSR matvec y = A x */
static void csr_matvec(int n, const int *indptr, const int *indices,
                       const double *data, const double *x, double *y) {
    for (int i = 0; i < n; i++) {
        double sum = 0.0;
        int start = indptr[i];
        int end = indptr[i+1];
        for (int j = start; j < end; j++) {
            sum += data[j] * x[indices[j]];
        }
        y[i] = sum;
    }
}

/* Returns info. Fills evals_r, evals_i (k+1) and evecs (n, k+1) Fortran order via dneupd.
   For now just run naupd and report ido/info/iter so we can validate the loop.
*/
int run_naupd(int n, int k, int ncv, int maxiter, int which, double tol,
              const int *indptr, const int *indices, const double *data,
              double *resid, double *v, double *workd, double *workl,
              int *ipntr, int *out_info, int *out_iter, int *out_nconv) {
    arnaud_state_d st;
    memset(&st, 0, sizeof(st));
    st.tol = tol;
    st.which = which;
    st.ido = 0;
    st.info = 1; /* starting vector provided */
    st.bmat = 0;
    st.mode = 1;
    st.n = n;
    st.ncv = ncv;
    st.nev = k;
    st.shift = 1;
    st.maxiter = maxiter;

    int guard = 0;
    int maxguard = maxiter * ncv + 100000;
    while (1) {
        ARNAUD_dnaupd(&st, resid, v, ipntr, workd, workl);
        int ido = st.ido;
        if (ido == 1 || ido == -1 || ido == 5) {
            int x0 = ipntr[0];
            int y0 = ipntr[1];
            csr_matvec(n, indptr, indices, data, workd + x0, workd + y0);
        } else if (ido == 2) {
            int x0 = ipntr[0];
            int y0 = ipntr[1];
            memcpy(workd + y0, workd + x0, n * sizeof(double));
        } else if (ido == 4) {
            /* shouldn't happen with info=1 */
            for (int i = 0; i < n; i++) resid[i] = 1.0;
        } else {
            break;
        }
        if (++guard > maxguard) {
            *out_info = -999;
            *out_iter = st.iter;
            *out_nconv = st.nconv;
            return -999;
        }
    }
    *out_info = st.info;
    *out_iter = st.iter;
    *out_nconv = st.nconv;
    return st.info;
}
