    int aitr_iter;         /* 0x74 */
    int aitr_j;            /* 0x78 */
    int aitr_orth1;        /* 0x7c */
    int aitr_orth2;        /* 0x80 */
    int aitr_restart;      /* 0x84 */
    int aitr_step3;        /* 0x88 */
    int aitr_step4;        /* 0x8c */
    int aitr_ierr;         /* 0x90 */
    int aup2_initv;        /* 0x94 */
    int aup2_iter;         /* 0x98 */
    int aup2_getv0;        /* 0x9c */
    int aup2_cnorm;        /* 0xa0 */
    int aup2_kplusp;       /* 0xa4 */
    int aup2_nev;          /* 0xa8 */
    int aup2_nev0;         /* 0xac */
    int aup2_np0;          /* 0xb0 */
    int aup2_numcnv;       /* 0xb4 */
    int aup2_update;       /* 0xb8 */
    int aup2_ushift;       /* 0xbc */
} arnaud_state_d;

extern void ARNAUD_dnaupd(arnaud_state_d *state, double *resid, double *v,
                          int *ldv_or_ipntr, double *workd, double *workl);

static void csr_matvec(int n, const int *indptr, const int *indices,
                       const double *data, const double *x, double *y) {
    for (int i = 0; i < n; i++) {
        double sum = 0.0;
        int start = indptr[i];
        int end = indptr[i + 1];
        for (int j = start; j < end; j++) {
            sum += data[j] * x[indices[j]];
        }
        y[i] = sum;
    }
}

int run_naupd(int n, int k, int ncv, int maxiter, int which, double tol,
              const int *indptr, const int *indices, const double *data,
              double *resid, double *v, double *workd, double *workl,
              int *ipntr, int *out_info, int *out_iter, int *out_nconv,
              int *out_ido) {
    arnaud_state_d st;
    memset(&st, 0, sizeof(st));
    st.tol = tol;
    st.which = which;
    st.ido = 0;
    st.info = 1;
    st.bmat = 0;
    st.mode = 1;
    st.n = n;
    st.ncv = ncv;
    st.nev = k;
    st.shift = 1;
    st.maxiter = maxiter;

    int guard = 0;
    int maxguard = maxiter * (ncv + 2) + 1000;
    while (1) {
        ARNAUD_dnaupd(&st, resid, v, ipntr, workd, workl);
        int ido = st.ido;
        if (ido == 1 || ido == -1 || ido == 5) {
            int x0 = ipntr[0];
            int y0 = ipntr[1];
            if (x0 < 0 || y0 < 0 || x0 + n > 3 * n || y0 + n > 3 * n) {
                *out_info = -998;
                *out_iter = st.iter;
                *out_nconv = st.nconv;
                *out_ido = ido;
                return -998;
            }
            csr_matvec(n, indptr, indices, data, workd + x0, workd + y0);
        } else if (ido == 2) {
            int x0 = ipntr[0];
            int y0 = ipntr[1];
            memcpy(workd + y0, workd + x0, (size_t)n * sizeof(double));
        } else if (ido == 4) {
            for (int i = 0; i < n; i++) resid[i] = 1.0;
        } else {
            *out_info = st.info;
            *out_iter = st.iter;
            *out_nconv = st.nconv;
            *out_ido = ido;
            return st.info;
        }
        if (++guard > maxguard) {
            *out_info = -999;
            *out_iter = st.iter;
            *out_nconv = st.nconv;
            *out_ido = st.ido;
            return -999;
        }
    }
}

int state_size(void) { return (int)sizeof(arnaud_state_d); }
