    int aup2_numcnv, aup2_update, aup2_ushift;
} arnaud_state_d;

extern void ARNAUD_dnaupd(arnaud_state_d *state, double *resid, double *v,
                          int ldv, int *ipntr, double *workd, double *workl);

static void csr_matvec(int n, const int *indptr, const int *indices,
                       const double *data, const double *x, double *y) {
    for (int i = 0; i < n; ++i) {
        double sum = 0.0;
        int a = indptr[i], b = indptr[i + 1];
        for (int j = a; j < b; ++j) sum += data[j] * x[indices[j]];
        y[i] = sum;
    }
}

/* Full naupd. workd/workl order: pass workd as the 6th C arg (r9) and workl on stack,
   matching the non-swapped experiment that at least wrote ipntr correctly.
   We also try an internal flag.
*/
int run_eigs(int n, int k, int ncv, int maxiter, int which,
             const int *indptr, const int *indices, const double *data,
             double *resid, double *v, double *workd, double *workl, int *ipntr,
             int *out_info, int *out_iter, int *out_nconv, int swap) {
    arnaud_state_d st;
    memset(&st, 0, sizeof(st));
    st.tol = 0.0;
    st.which = which;
    st.ido = 0;
    st.info = 1;
    st.bmat = 0;
    st.mode = 1;
    st.n = n;
    st.ncv = ncv;
    st.nev = k;
    st.shift = 1;
    st.maxiter = maxiter;

    int guard = 0;
    int limit = maxiter * (ncv + 5) + 100;
    while (1) {
        if (swap)
            ARNAUD_dnaupd(&st, resid, v, n, ipntr, workl, workd);
        else
            ARNAUD_dnaupd(&st, resid, v, n, ipntr, workd, workl);
        int ido = st.ido;
        if (ido == 1 || ido == -1 || ido == 5) {
            int x0 = ipntr[0];
            int y0 = ipntr[1];
            double *base = swap ? workl : workd;
            /* if swap, the "workd" buffer the solver uses is what we passed as r9 = workl.
               So x/y live in workl. That's confusing. Handle both. */
            if (swap) {
                csr_matvec(n, indptr, indices, data, workl + x0, workl + y0);
            } else {
                csr_matvec(n, indptr, indices, data, workd + x0, workd + y0);
            }
            (void)base;
        } else if (ido == 2) {
            int x0 = ipntr[0], y0 = ipntr[1];
            if (swap) memcpy(workl + y0, workl + x0, (size_t)n * sizeof(double));
            else memcpy(workd + y0, workd + x0, (size_t)n * sizeof(double));
        } else if (ido == 4) {
            for (int i = 0; i < n; i++) resid[i] = 1.0;
        } else {
            break;
        }
        if (++guard > limit) {
            *out_info = -999; *out_iter = st.iter; *out_nconv = st.nconv;
            return -999;
        }
    }
    *out_info = st.info;
    *out_iter = st.iter;
    *out_nconv = st.nconv;
    /* copy state back into the front of workl? return via out only */
    /* stash state into resid? no. Return nconv/info is enough for now.
       Also write state into a side channel: overwrite first ints of ipntr tail? 
       We'll copy state bytes into workl's end... skip. */
    return st.info;
}
