extern void ARNAUD_dnaupd(arnaud_state_d *state, double *resid, double *v,
                          int ldv, int *ipntr, double *workd, double *workl);

/* Register order inferred from dneupd_wrap:
   rdi=state, esi=rvec, edx=howmny, rcx=select, r8=dr, r9=di,
   stack (right to left pushes, so first push is last arg):
     workl, workd, ipntr, resid, v, ldv? , z, sigmai, sigmar, workev
   Pushes in order: r15, rbx, -0xd0, r14, r13, -0xb0, -0xc0, r12, -0xc8
   Need to map those. We'll expose a raw call and also a guessed one.
*/
extern void ARNAUD_dneupd(arnaud_state_d *state, int rvec, int howmny,
                          int *select, double *dr, double *di,
                          double *z, double sigmar, double sigmai, double *workev,
                          double *resid, double *v, int *ipntr,
                          double *workd, double *workl);

static void csr_matvec(int n, const int *indptr, const int *indices,
                       const double *data, const double *x, double *y) {
    int i, j;
    for (i = 0; i < n; ++i) {
        double sum = 0.0;
        for (j = indptr[i]; j < indptr[i + 1]; ++j)
            sum += data[j] * x[indices[j]];
        y[i] = sum;
    }
}

int run_eigs(int n, int k, int ncv, int maxiter, int which, double tol,
             const int *indptr, const int *indices, const double *data,
             double *resid, double *v, double *workd, double *workl, int *ipntr,
             double *dr, double *di, double *z, int *select, double *workev,
             int *out_nconv, int *out_info) {
    arnaud_state_d st;
    memset(&st, 0, sizeof(st));
    st.tol = tol;
    st.which = which;
    st.ido = 0;
    st.info = 1;
    st.bmat = 0;
    st.mode = 1;
    st.n = n;
    st.ncv = ncv;
    st.nev = k;
    st.shift = 1;
    st.maxiter = maxiter;

    for (;;) {
        ARNAUD_dnaupd(&st, resid, v, n, ipntr, workd, workl);
        int ido = st.ido;
        if (ido == 1 || ido == -1 || ido == 5) {
            csr_matvec(n, indptr, indices, data, workd + ipntr[0], workd + ipntr[1]);
        } else if (ido == 2) {
            memcpy(workd + ipntr[1], workd + ipntr[0], (size_t)n * sizeof(double));
        } else if (ido == 4) {
            int i;
            for (i = 0; i < n; i++) resid[i] = 1.0;
        } else break;
    }
    *out_info = st.info;
    *out_nconv = st.nconv;
    if (st.info != 0 && st.info != 1) return st.info;

    st.info = 0;
    /* howmny = 0 means 'A' (all), matching HOWMNY_DICT typically 0. Caller passes via which? 
       We hardcode howmny=0. */
    ARNAUD_dneupd(&st, 1, 0, select, dr, di, z, 0.0, 0.0, workev,
                  resid, v, ipntr, workd, workl);
    *out_info = st.info;
    *out_nconv = st.nconv;
    return st.info;
}
