extern void ARNAUD_dnaupd(arnaud_state_d *state, double *resid, double *v,
                          int ldv, int *ipntr, double *workd, double *workl);

#define NTHREADS 4

typedef struct {
    int n0, n1;
    const int *indptr, *indices;
    const double *data, *x;
    double *y;
} job_t;

static job_t jobs[NTHREADS];
static pthread_t threads[NTHREADS];
static pthread_mutex_t mtx = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t cv_go = PTHREAD_COND_INITIALIZER;
static pthread_cond_t cv_done = PTHREAD_COND_INITIALIZER;
static int go_epoch = 0;
static int done_count = 0;
static int stop = 0;
static int started = 0;

static void *worker(void *arg) {
    int id = (int)(intptr_t)arg;
    int seen = 0;
    for (;;) {
        pthread_mutex_lock(&mtx);
        while (go_epoch == seen && !stop) pthread_cond_wait(&cv_go, &mtx);
        if (stop) { pthread_mutex_unlock(&mtx); break; }
        seen = go_epoch;
        pthread_mutex_unlock(&mtx);

        job_t *jb = &jobs[id];
        const int *indptr = jb->indptr, *indices = jb->indices;
        const double *data = jb->data, *x = jb->x;
        double *y = jb->y;
        int i;
        for (i = jb->n0; i < jb->n1; ++i) {
            double sum = 0.0;
            int j, a = indptr[i], b = indptr[i + 1];
            for (j = a; j < b; ++j) sum += data[j] * x[indices[j]];
            y[i] = sum;
        }

        pthread_mutex_lock(&mtx);
        done_count++;
        if (done_count == NTHREADS) pthread_cond_signal(&cv_done);
        pthread_mutex_unlock(&mtx);
    }
    return NULL;
}

static void ensure_threads(void) {
    if (started) return;
    int i;
    for (i = 0; i < NTHREADS; i++)
        pthread_create(&threads[i], NULL, worker, (void *)(intptr_t)i);
    started = 1;
}

static void csr_matvec_mt(int n, const int *indptr, const int *indices,
                          const double *data, const double *x, double *y) {
    ensure_threads();
    int i, chunk = (n + NTHREADS - 1) / NTHREADS;
    for (i = 0; i < NTHREADS; i++) {
        jobs[i].n0 = i * chunk;
        jobs[i].n1 = jobs[i].n0 + chunk;
        if (jobs[i].n1 > n) jobs[i].n1 = n;
        if (jobs[i].n0 > n) jobs[i].n0 = n;
        jobs[i].indptr = indptr;
        jobs[i].indices = indices;
        jobs[i].data = data;
        jobs[i].x = x;
        jobs[i].y = y;
    }
    pthread_mutex_lock(&mtx);
    done_count = 0;
    go_epoch++;
    pthread_cond_broadcast(&cv_go);
    while (done_count < NTHREADS) pthread_cond_wait(&cv_done, &mtx);
    pthread_mutex_unlock(&mtx);
}

int run_naupd(int n, int k, int ncv, int maxiter, int which, double tol,
              const int *indptr, const int *indices, const double *data,
              double *resid, double *v, double *workd, double *workl, int *ipntr,
