#include <string.h>
#include <pthread.h>
#include <stdlib.h>
#include <stdatomic.h>
#include <stdint.h>

typedef struct {
    double tol, getv0_rnorm0, aitr_betaj, aitr_rnorm1, aitr_wnorm, aup2_rnorm;
    int which, ido, info, bmat, mode, n, ncv, nev, shift, maxiter, nconv, iter, np;
    int getv0_first, getv0_iter, getv0_itry, getv0_orth;
    int aitr_iter, aitr_j, aitr_orth1, aitr_orth2, aitr_restart, aitr_step3, aitr_step4, aitr_ierr;
    int aup2_initv, aup2_iter, aup2_getv0, aup2_cnorm, aup2_kplusp, aup2_nev, aup2_nev0, aup2_np0;
    int aup2_numcnv, aup2_update, aup2_ushift;
} arnaud_state_d;

extern void ARNAUD_dnaupd(arnaud_state_d *state, double *resid, double *v,
                          int ldv, int *ipntr, double *workd, double *workl);

#define MAXTHREADS 8
static int nthreads = 1;

typedef struct {
    int n0, n1;
    const int *indptr, *indices;
    const double *data, *x;
    double *y;
} job_t;

static job_t jobs[MAXTHREADS];
static pthread_t threads[MAXTHREADS];
static atomic_int go_epoch = 0;
static atomic_int done_count = 0;
static atomic_int stop_flag = 0;
static int started = 0;

static void *worker(void *arg) {
    int id = (int)(intptr_t)arg;
    int seen = 0;
    for (;;) {
        int e;
        while ((e = atomic_load_explicit(&go_epoch, memory_order_acquire)) == seen) {
            if (atomic_load_explicit(&stop_flag, memory_order_acquire)) return NULL;
#if defined(__x86_64__)
            __asm__ __volatile__("pause");
#else
            __asm__ __volatile__("yield");
#endif
        }
        seen = e;
        job_t *jb = &jobs[id];
        const int *indptr = jb->indptr, *indices = jb->indices;
        const double *data = jb->data, *x = jb->x;
        double *y = jb->y;
        int i;
        for (i = jb->n0; i < jb->n1; ++i) {
            double sum = 0.0;
            int a = indptr[i], b = indptr[i + 1];
            int j = a;
            /* unroll by 4 */
            for (; j + 3 < b; j += 4) {
                sum += data[j] * x[indices[j]];
                sum += data[j + 1] * x[indices[j + 1]];
                sum += data[j + 2] * x[indices[j + 2]];
                sum += data[j + 3] * x[indices[j + 3]];
            }
            for (; j < b; ++j) sum += data[j] * x[indices[j]];
            y[i] = sum;
        }
        atomic_fetch_add_explicit(&done_count, 1, memory_order_release);
    }
    return NULL;
}

static void ensure_threads(void) {
    if (started) return;
    if (nthreads < 1) nthreads = 1;
    if (nthreads > MAXTHREADS) nthreads = MAXTHREADS;
    int i;
    for (i = 1; i < nthreads; i++)   /* thread 0 is the caller */
        pthread_create(&threads[i], NULL, worker, (void *)(intptr_t)i);
    started = 1;
}

static void csr_matvec(int n, const int *indptr, const int *indices,
                       const double *data, const double *x, double *y) {
    if (nthreads <= 1) {
        int i;
        for (i = 0; i < n; ++i) {
            double sum = 0.0;
            int a = indptr[i], b = indptr[i + 1], j = a;
            for (; j + 3 < b; j += 4) {
                sum += data[j] * x[indices[j]] + data[j+1] * x[indices[j+1]]
                     + data[j+2] * x[indices[j+2]] + data[j+3] * x[indices[j+3]];
            }
            for (; j < b; ++j) sum += data[j] * x[indices[j]];
            y[i] = sum;
        }
        return;
    }
    ensure_threads();
    int nt = nthreads;
    int chunk = (n + nt - 1) / nt;
    int i;
    for (i = 0; i < nt; i++) {
        jobs[i].n0 = i * chunk;
        int n1 = jobs[i].n0 + chunk;
        if (n1 > n) n1 = n;
        if (jobs[i].n0 > n) jobs[i].n0 = n;
        jobs[i].n1 = n1;
        jobs[i].indptr = indptr;
        jobs[i].indices = indices;
        jobs[i].data = data;
        jobs[i].x = x;
        jobs[i].y = y;
    }
    atomic_store_explicit(&done_count, 0, memory_order_relaxed);
    /* publish jobs then bump epoch */
    atomic_fetch_add_explicit(&go_epoch, 1, memory_order_release);

    /* do thread 0's share inline */
    {
        job_t *jb = &jobs[0];
        for (i = jb->n0; i < jb->n1; ++i) {
            double sum = 0.0;
            int a = indptr[i], b = indptr[i + 1], j = a;
            for (; j + 3 < b; j += 4) {
                sum += data[j] * x[indices[j]] + data[j+1] * x[indices[j+1]]
                     + data[j+2] * x[indices[j+2]] + data[j+3] * x[indices[j+3]];
            }
            for (; j < b; ++j) sum += data[j] * x[indices[j]];
            y[i] = sum;
        }
    }
    while (atomic_load_explicit(&done_count, memory_order_acquire) < nt - 1) {
#if defined(__x86_64__)
        __asm__ __volatile__("pause");
#else
        __asm__ __volatile__("yield");
#endif
    }
}

void set_threads(int n) { nthreads = n; }

int run_naupd(int n, int k, int ncv, int maxiter, int which, double tol,
              const int *indptr, const int *indices, const double *data,
              double *resid, double *v, double *workd, double *workl, int *ipntr,
              void *state_out) {
    arnaud_state_d st;
    memset(&st, 0, sizeof(st));
    st.tol = tol; st.which = which; st.ido = 0; st.info = 1; st.bmat = 0;
    st.mode = 1; st.n = n; st.ncv = ncv; st.nev = k; st.shift = 1; st.maxiter = maxiter;
    for (;;) {
        ARNAUD_dnaupd(&st, resid, v, n, ipntr, workd, workl);
        int ido = st.ido;
        if (ido == 1 || ido == -1 || ido == 5)
            csr_matvec(n, indptr, indices, data, workd + ipntr[0], workd + ipntr[1]);
        else if (ido == 2)
            memcpy(workd + ipntr[1], workd + ipntr[0], (size_t)n * sizeof(double));
        else if (ido == 4) {
            int i; for (i = 0; i < n; ++i) resid[i] = 1.0;
        } else break;
    }
    if (state_out) memcpy(state_out, &st, sizeof(st));
    return st.info;
}
