typedef void (*dneupd_fn)(arnaud_state_d *state, int rvec, int howmny,
                          int *select, double *dr, double *di,
                          double *z, double sigmar, double sigmai, double *workev,
                          double *resid, double *v, int ldv, int *ipntr,
                          double *workd, double *workl);

extern void ARNAUD_dneupd(void);

/* variant: ldv by value inserted at different stack positions.
   We just call the guessed signature and return info. */
int try_call(int variant,
             void *state, int n, int ncv, int k,
             double *resid, double *v, double *workd, double *workl, int *ipntr,
             double *dr, double *di, double *z, int *select, double *workev) {
    arnaud_state_d *st = (arnaud_state_d *)state;
    st->info = 0;
    dneupd_fn fn = (dneupd_fn)ARNAUD_dneupd;
    if (variant == 0) {
        /* z is first stack arg after di (r9). sigmas in xmm. ldv by value before ipntr. */
        fn(st, 1, 0, select, dr, di, z, 0.0, 0.0, workev, resid, v, n, ipntr, workd, workl);
    } else if (variant == 1) {
        /* no ldv, ipntr is pointer where ldv was */
        typedef void (*fn1)(arnaud_state_d*, int, int, int*, double*, double*,
                            double*, double, double, double*,
                            double*, double*, int*, double*, double*);
        ((fn1)ARNAUD_dneupd)(st, 1, 0, select, dr, di, z, 0.0, 0.0, workev, resid, v, ipntr, workd, workl);
    } else if (variant == 2) {
        /* workd/workl swapped, with ldv */
        fn(st, 1, 0, select, dr, di, z, 0.0, 0.0, workev, resid, v, n, ipntr, workl, workd);
    } else if (variant == 3) {
        /* howmny passed differently? try rvec as pointer? skip */
        typedef void (*fn3)(arnaud_state_d*, int, int, int*, double*, double*,
                            double, double, double*, double*,
                            double*, double*, int, int*, double*, double*);
        /* z not in regs: dr, di in regs, sigmas, then workev, z ... unlikely */
        ((fn3)ARNAUD_dneupd)(st, 1, 0, select, dr, di, 0.0, 0.0, workev, z, resid, v, n, ipntr, workd, workl);
    }
    return st->info;
}
