#include <stddef.h>
#include <math.h>

/* NEWLAPACK-suffixed BLAS used by scipy's ARPACK. Interpose the level-1
   kernels, which dominate the tiny-vector Arnoldi update. */

void daxpy$NEWLAPACK(const int *n, const double *alpha, const double *x,
                     const int *incx, double *y, const int *incy) {
    int nn = *n, ix = *incx, iy = *incy;
    if (nn <= 0) return;
    double a = *alpha;
    if (a == 0.0) return;
    if (ix == 1 && iy == 1) {
        int i = 0;
        for (; i + 3 < nn; i += 4) {
            y[i] += a * x[i];
            y[i+1] += a * x[i+1];
            y[i+2] += a * x[i+2];
            y[i+3] += a * x[i+3];
        }
        for (; i < nn; ++i) y[i] += a * x[i];
        return;
    }
    int i, kx = ix < 0 ? (1-nn)*ix : 0, ky = iy < 0 ? (1-nn)*iy : 0;
    for (i = 0; i < nn; ++i) { y[ky] += a * x[kx]; kx += ix; ky += iy; }
}

void dscal$NEWLAPACK(const int *n, const double *alpha, double *x, const int *incx) {
    int nn = *n, ix = *incx;
    if (nn <= 0) return;
    double a = *alpha;
    if (ix == 1) {
        int i = 0;
        for (; i + 3 < nn; i += 4) {
            x[i] *= a; x[i+1] *= a; x[i+2] *= a; x[i+3] *= a;
        }
        for (; i < nn; ++i) x[i] *= a;
        return;
    }
    int i, k = ix < 0 ? (1-nn)*ix : 0;
    for (i = 0; i < nn; ++i) { x[k] *= a; k += ix; }
}

void dcopy$NEWLAPACK(const int *n, const double *x, const int *incx, double *y, const int *incy) {
    int nn = *n, ix = *incx, iy = *incy;
    if (nn <= 0) return;
    if (ix == 1 && iy == 1) {
        int i = 0;
        for (; i + 3 < nn; i += 4) {
            y[i]=x[i]; y[i+1]=x[i+1]; y[i+2]=x[i+2]; y[i+3]=x[i+3];
        }
        for (; i < nn; ++i) y[i] = x[i];
        return;
    }
    int i, kx = ix < 0 ? (1-nn)*ix : 0, ky = iy < 0 ? (1-nn)*iy : 0;
    for (i = 0; i < nn; ++i) { y[ky] = x[kx]; kx += ix; ky += iy; }
}

double ddot$NEWLAPACK(const int *n, const double *x, const int *incx,
                      const double *y, const int *incy) {
    int nn = *n, ix = *incx, iy = *incy;
    if (nn <= 0) return 0.0;
    double s = 0.0;
    if (ix == 1 && iy == 1) {
        int i = 0;
        for (; i + 3 < nn; i += 4)
            s += x[i]*y[i] + x[i+1]*y[i+1] + x[i+2]*y[i+2] + x[i+3]*y[i+3];
        for (; i < nn; ++i) s += x[i]*y[i];
        return s;
    }
    int i, kx = ix < 0 ? (1-nn)*ix : 0, ky = iy < 0 ? (1-nn)*iy : 0;
    for (i = 0; i < nn; ++i) { s += x[kx]*y[ky]; kx += ix; ky += iy; }
    return s;
}

double dnrm2$NEWLAPACK(const int *n, const double *x, const int *incx) {
    int nn = *n, ix = *incx;
    if (nn <= 0) return 0.0;
    double s = 0.0;
    if (ix == 1) {
        int i = 0;
        double c = 0.0;
        for (; i + 3 < nn; i += 4) {
            s += x[i]*x[i] + x[i+1]*x[i+1] + x[i+2]*x[i+2] + x[i+3]*x[i+3];
        }
        for (; i < nn; ++i) s += x[i]*x[i];
        (void)c;
        return sqrt(s);
    }
    int i, k = ix < 0 ? (1-nn)*ix : 0;
    for (i = 0; i < nn; ++i) { s += x[k]*x[k]; k += ix; }
    return sqrt(s);
}

void dswap$NEWLAPACK(const int *n, double *x, const int *incx, double *y, const int *incy) {
    int nn = *n, ix = *incx, iy = *incy;
    if (nn <= 0) return;
    if (ix == 1 && iy == 1) {
        int i;
        for (i = 0; i < nn; ++i) { double t = x[i]; x[i] = y[i]; y[i] = t; }
        return;
    }
    int i, kx = ix < 0 ? (1-nn)*ix : 0, ky = iy < 0 ? (1-nn)*iy : 0;
    for (i = 0; i < nn; ++i) { double t = x[kx]; x[kx] = y[ky]; y[ky] = t; kx += ix; ky += iy; }
}

void drot$NEWLAPACK(const int *n, double *x, const int *incx, double *y, const int *incy,
                    const double *c, const double *s) {
    int nn = *n, ix = *incx, iy = *incy;
    if (nn <= 0) return;
    double cc = *c, ss = *s;
    if (ix == 1 && iy == 1) {
        int i;
        for (i = 0; i < nn; ++i) {
            double xi = x[i], yi = y[i];
            x[i] = cc*xi + ss*yi;
            y[i] = cc*yi - ss*xi;
        }
        return;
    }
    int i, kx = ix < 0 ? (1-nn)*ix : 0, ky = iy < 0 ? (1-nn)*iy : 0;
    for (i = 0; i < nn; ++i) {
        double xi = x[kx], yi = y[ky];
        x[kx] = cc*xi + ss*yi;
        y[ky] = cc*yi - ss*xi;
        kx += ix; ky += iy;
    }
}
